app.get('{{path}}', async (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  const lastId = Number(req.header('Last-Event-ID') || 0);
  const missed = await store.eventsAfter(lastId);
  for (const e of missed) res.write(`id: ${e.id}\ndata: ${JSON.stringify(e.payload)}\n\n`);
  store.on('event', (e) => res.write(`id: ${e.id}\ndata: ${JSON.stringify(e.payload)}\n\n`));
});
